describe('Unsaved Form Warning', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/form');
    cy.get('form').should('be.visible');
  });

  it('should display warning when navigating away with unsaved changes', () => {
    cy.get('input[name="email"]').type('test@example.com');
    cy.get('input[name="name"]').type('John Doe');

    cy.window().then((win) => {
      cy.stub(win, 'confirm').returns(false);
    });

    cy.get('a[href="/other-page"]').click();

    cy.window().its('confirm').should('have.been.calledWith', 'You have unsaved changes. Do you want to leave?');
  });

  it('should allow navigation when user confirms leaving unsaved form', () => {
    cy.get('input[name="email"]').type('test@example.com');

    cy.window().then((win) => {
      cy.stub(win, 'confirm').returns(true);
    });

    cy.get('a[href="/other-page"]').click();

    cy.url().should('include', '/other-page');
  });

  it('should not show warning when form has no changes', () => {
    cy.window().then((win) => {
      cy.stub(win, 'confirm');
    });

    cy.get('a[href="/other-page"]').click();

    cy.window().its('confirm').should('not.have.been.called');
    cy.url().should('include', '/other-page');
  });

  it('should not show warning after successful form submission', () => {
    cy.get('input[name="email"]').type('test@example.com');
    cy.get('input[name="name"]').type('Jane Doe');
    cy.get('button[type="submit"]').click();

    cy.get('.success-message').should('be.visible');

    cy.window().then((win) => {
      cy.stub(win, 'confirm');
    });

    cy.get('a[href="/other-page"]').click();

    cy.window().its('confirm').should('not.have.been.called');
  });

  it('should show warning when only one field is modified', () => {
    cy.get('input[name="email"]').type('modified@example.com');

    cy.window().then((win) => {
      cy.stub(win, 'confirm').returns(false);
    });

    cy.get('a[href="/other-page"]').click();

    cy.window().its('confirm').should('have.been.called');
    cy.url().should('include', '/form');
  });

  it('should clear warning state when user cancels navigation and continues editing', () => {
    cy.get('input[name="email"]').type('test@example.com');

    cy.window().then((win) => {
      cy.stub(win, 'confirm').returns(false);
    });

    cy.get('a[href="/other-page"]').click();
    cy.window().its('confirm').should('have.been.called');

    cy.get('input[name="name"]').type('John Doe');
    cy.get('button[type="submit"]').click();

    cy.get('.success-message').should('be.visible');
  });
});
